                        System.out.println(gcd(a,b) + " " + lcm(a,b));
                }   
                sc.close();
        }   
        static int gcd(int a, int b){
                if(a < b){ 
                        int tmp = a;
                        a = b;
                        b = tmp;
                }   
                do{ 
                        int r = a%b;
                        a = b;
                        b = r;
                }while(b != 0); 
                return a;
        }   
        static int lcm(int a, int b){
                int _a = a;
                int _b = b;
                while(_a != _b){
                        if(_a < _b){
                                _a += a;
                        }else{
                                _b += b;
                        }   
                }   
                return _a; 
        }   
}

import java.util.Scanner;
public class Main {
    public static void main (String[] args) {
	Scanner scan = new Scanner(System.in);
	long a, b;
	String[] input;
	while (scan.hasNext()){
	    input = scan.nextLine().split(" ");
	    a = Integer.parseInt(input[0]);
	    b = Integer.parseInt(input[1]);
	    long lcm = solveLCM(a, b);
	    long gcd = solveGCD(a, b);
	    System.out.println(gcd + " " + lcm);
	}
    }
    static long solveGCD (long a, long b) {
	long gcd = a % b;
	if (gcd == 0) {
	    return b;
	}
	return solveGCD(b, gcd);
    }

    static long solveLCM (long a, long b) {
	if (a == 0 || b == 0) {
	    return 0;
	}
	return a * b / solveGCD(a,b);
    }
}

import java.io.IOException;
import java.util.Scanner;


public class Main{

	public static void main(String[] args) throws IOException {
		Scanner scan = new Scanner(System.in);
		while (scan.hasNext()) {
			long a = scan.nextLong();
			long b = scan.nextLong();
			long gcd = divide(a, b);

			long lcm = a * b / gcd;
			System.out.println(gcd + " " + lcm);

		}
	}

	public static long divide(long a, long b) {
		long r;
		if (a < b) {
			long temp = b;
			b = a;
			a = temp;
		}
		r = a % b;

		return r == 0 ? b : divide(b, r);
	}

}

import java.util.Scanner;


public class Main{

	public static void main(String[] args){

		Scanner sc = new Scanner(System.in);
		long a, b;
		while(sc.hasNext()) {
			a = sc.nextLong();
			b = sc.nextLong();
			System.out.println(LCM(a, b) + " " + GCD(a, b));
		}
		sc.close();
	}

	static long GCD(long a, long b) {
		return a * b / LCM(a, b);
	}

	static long LCM(long a, long b) {
		long n0 = (a >= b) ? a: b;
		long n1 = (a >= b) ? b: a;

		if(n1 == 0) return n0;
		else return LCM(n1, n0 % n1);
	}
}

