			} else if ("*".equals(s)) {
				int a = Integer.parseInt(stack.pop());
				int b = Integer.parseInt(stack.pop());
				stack.push(String.valueOf(a * b));
			} else {
				stack.push(s);
			}
		}
		System.out.println(stack.pop());
	}
}

