        }
        int sum = 0;
        int ans_matrix[][] = new int[r + 1][c + 1];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                ans_matrix[i][j] = matrix[i][j];
                ans_matrix[i][c] += matrix[i][j];
            }
            sum += ans_matrix[i][c];
        }
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                ans_matrix[r][j] += matrix[i][j];
            }
        }
        ans_matrix[r][c] = sum;

        for (int i = 0; i < ans_matrix.length; i++) {
            for (int j = 0; j < ans_matrix[i].length; j++) {
