        BigInteger bi = new BigInteger(fs.next());
        BigInteger twentySix = new BigInteger("26");
        StringBuilder sb = new StringBuilder();
        while(bi.compareTo(BigInteger.ZERO)  != 0 ){
            BigInteger k = bi.divide(twentySix);
