class ATCoder_abc159_c {
    // Per Euclidean math, largest possible volume is a cube.
	public static double largestVolume(int L) {
		double lOver3 = (double) L / 3.0;
		double volume = lOver3 * lOver3 * lOver3;
      	return volume;
	}
}

