            long left = Math.min(a[i], b[i]);
            long right = Math.min(a[i + 1], b[i] - left);
            a[i + 1] -= right;
            hunteredNumber += left + right;
        }
        System.out.println(hunteredNumber);
        sc.close();
    }
}

