            for (int j = i + 1; j < N; j++) {
                String[] z = arr2[j];
                ans += check(D, y, z);
            }
        }

        out.println(ans);
        out.close();
    }

    private static int check(int D, String[] arr1, String[] arr2) {
        int sum = 0;
        for (int i = 0; i < D; i++) {
            int y = Integer.parseInt(arr1[i]);
            int z = Integer.parseInt(arr2[i]);
            sum += Math.pow(y - z, 2);
        }
        double sqrt = Math.sqrt(sum);
        return sqrt % 1 == 0 ? 1 : 0;
    }
}

import java.util.*;

public class Main {

	public static boolean dis(int x[], int y[], int d){
		long ans = 0;
		for(int i = 0; i < d; ++i){
			int tmpx = x[i];
			int tmpy = y[i];
			ans += (tmpx - tmpy) * (tmpx - tmpy);
		}
		double ansd = Math.sqrt((double)ans);
		return (ansd == Math.floor(ansd));
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), d = sc.nextInt();
		int x[][] = new int[n][d];
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < d; ++j)
				x[i][j] = sc.nextInt();
		sc.close();
		int ans = 0;
		for(int i = 0; i < n;++i){
			for(int j = i + 1; j < n; ++j){
				if(dis(x[i], x[j], d))++ans;
			}
		}

		System.out.println(ans);
	}
}

