  	public static void solve_abc126_c() {

		FastScanner sc = new FastScanner(System.in);

		int n = sc.nextInt();
		int k = sc.nextInt();

		double prob = 0;
		double logk1 = Math.log(k-1);
		double log2 = Math.log(2.0);

		for(int i=1;i<=n;i++){

			if(i >= k){
				prob += 1.0 / (double) n;
			}
			else{
				int coin = (int)((logk1 - Math.log(i)) / log2) + 1;
				prob += 1.0 / (Math.pow(2.0, coin) * (double)n );
			}
		}

		System.out.println(prob);
	}

}

