        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] v = new int[n];
            int[] c = new int[n];
            for (int i = 0; i < n; i++)
                v[i] = in.nextInt();
            for (int i = 0; i < n; i++)
                c[i] = in.nextInt();
            int max = 0;
            for (int i = 0, lim = 1 << n; i < lim; i++) {
