                for(int j=1; j<=b; j++) {
                    if(b % j == 0 && i == j) {
                        ans.add(i);
                    }
                }
            }
        }

        Collections.sort(ans, Collections.reverseOrder());
        System.out.println(ans.get(k-1));
    }
}

