    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        int answer = 0;
        int current = 0;
        for (int i = 0; i < N; i++) {
            int h = scan.nextInt();
            if (current <= h) {
                answer += (h - current);
            }
            current = h;
        }
        System.out.println(answer);
    }
}

