import java.io.PrintWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.StringTokenizer;
import java.math.BigInteger;

public class Main {
    static InputReader in = new InputReader(System.in);
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        String s = in.next();
        int[] a = new int[4];
        for(int i = 0; i<4; i++){
            a[i] = Integer.parseInt(s.substring(i,i+1));
        }
        boolean check = true;
        for(int i = 0; i<2; i++){
            for(int j = 0; j<2; j++){
                for(int k = 0; k<2; k++){
                    int sum = a[0];
                    String[] c = new String[3];
                    if(i==0){
                        sum += a[1];
                        c[0] = "+";
                    }
                    else{
                        sum -= a[1];
                        c[0] = "-";
                    }
                    if(j==0){
                        sum += a[2];
                        c[1] = "+";
                    }
                    else{
                        sum -= a[2];
                        c[1] = "-";
                    }if(k==0){
                        sum += a[3];
                        c[2] = "+";
                    }
                    else{
                        sum -= a[3];
                        c[2] = "-";
                    }
                    if(sum==7){
                        out.println(a[0] + c[0] + a[1] + c[1] + a[2] + c[2] + a[3]+"=7");
                        check = false;
                        break;
                    }
                }
                if(!check) break;
            }
            if(!check) break;
        }
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return null;
        }

        public boolean hasNext() {
            String next = null;
            try {
                next = reader.readLine();
            } catch (Exception e) {
            }
            if (next == null) {
                return false;
            }
            tokenizer = new StringTokenizer(next);
            return true;
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }
    }
}

import java.io.*;
import java.util.*;
public class Main {
    static String oper;
    public static void main(String args[]) throws Exception {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        char[] chs = s.toCharArray();

        String oper = dfs(chs, 1, chs[0] - '0', "");
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < chs.length; i++) {
            sb.append(chs[i]);
            if(i < chs.length - 1)
                sb.append(oper.charAt(i));
        }  
        System.out.println(sb.toString() + "=7");
    }
    /*
     1 2 2 2
      ^ 
     cur = 1+2=3+2=7 oper = "+++"
    */
    private static String dfs(char[] chs, int idx, int cur, String opers) {
        if(idx == chs.length) {
            if(cur == 7)
                return opers;
            else return null;
        }

        String plus = dfs(chs, idx + 1, cur + (chs[idx] - '0'), opers + "+");
        if(plus != null)
            return plus;

        String nega = dfs(chs, idx + 1, cur - (chs[idx] - '0'), opers + "-");
        if(nega != null)
            return nega;

        return null;
    }
}

