        for (int i = 0; i < (1<<len); i++) {
            StringBuilder sb = new StringBuilder().append(sc[0]);
            int sum = Character.getNumericValue(sc[0]);
            for (int k = 1; k  < len; k++) {
                if ((1 & (i >> k)) == 1) {
                    sb.append("+" + sc[k]);
                    sum += Character.getNumericValue(sc[k]);
